import sys
import json
import base64
import hashlib
from email.utils import formatdate


def validate_request(data):
    if not isinstance(data, dict):
        return False
    required = ['from', 'to', 'subject', 'date', 'message_id', 'body', 'attachments']
    for f in required:
        if f not in data:
            return False
    if not isinstance(data['from'], str):
        return False
    if not isinstance(data['to'], list):
        return False
    if not (1 <= len(data['to']) <= 8):
        return False
    for t in data['to']:
        if not isinstance(t, str):
            return False
    if not isinstance(data['subject'], str) or len(data['subject']) == 0:
        return False
    if not isinstance(data['date'], int) or isinstance(data['date'], bool):
        return False
    if not isinstance(data['message_id'], str):
        return False
    if not (data['message_id'].startswith('<') and data['message_id'].endswith('>')):
        return False
    if not isinstance(data['body'], str):
        return False
    if not isinstance(data['attachments'], list):
        return False
    if len(data['attachments']) > 8:
        return False
    for att in data['attachments']:
        if not isinstance(att, dict):
            return False
        for af in ['filename', 'content_type', 'content_b64']:
            if af not in att:
                return False
        if not isinstance(att['filename'], str) or not att['filename']:
            return False
        if '/' not in att['content_type'] or not isinstance(att['content_type'], str):
            return False
        if not isinstance(att['content_b64'], str):
            return False
        try:
            decoded = base64.b64decode(att['content_b64'], validate=True)
            if len(decoded) > 64 * 1024:
                return False
        except Exception:
            return False
    return True


def rfc2047_encode(text):
    try:
        text.encode('ascii')
        return text
    except UnicodeEncodeError:
        pass
    from email.header import Header
    h = Header()
    h.append(text, 'utf-8')
    return h.encode()


def rfc2231_encode_filename(filename):
    try:
        filename.encode('ascii')
        return None
    except UnicodeEncodeError:
        pass
    utf8_bytes = filename.encode('utf-8')
    encoded = ''.join(f'%{b:02X}' for b in utf8_bytes)
    return f"UTF-8''{encoded}"


def format_date_str(epoch):
    return formatdate(timeval=epoch, localtime=False, usegmt=False)


def base64_wrap(s, max_len=76):
    if not s:
        return ''
    return '\r\n'.join(s[i:i+max_len] for i in range(0, len(s), max_len))


def build_part_header(content_type, extra_headers=None):
    """Build MIME part headers. Returns string with headers ending in \\r\\n\\r\\n"""
    lines = [f'Content-Type: {content_type}']
    if extra_headers:
        for key, val in extra_headers:
            lines.append(f'{key}: {val}')
    return '\r\n'.join(lines) + '\r\n'


def main():
    try:
        data = json.loads(sys.stdin.read())
    except Exception:
        print(json.dumps({"error": "invalid_request"}))
