    try:
        from_addr = data['from']
        to_addrs = data['to']
        subject = data['subject']
        date_epoch = data['date']
        message_id = data['message_id']
        body = data['body']
        attachments = data['attachments']

        subject_encoded = rfc2047_encode(subject)

        headers = [
            f'From: {from_addr}',
            f'To: {", ".join(to_addrs)}',
            f'Subject: {subject_encoded}',
            f'Date: {format_date_str(date_epoch)}',
            f'Message-ID: {message_id}',
            'MIME-Version: 1.0',
        ]

        header_text = '\r\n'.join(headers) + '\r\n'

        boundary = '----=_Part_0_AbCdEfGhIjKlMnOpQrSt'

